insert into public.tests (id, slug, title, subtitle, test_type, section_scope, focus_domain_id, difficulty, description, sort_order) values ('6a599338-97a5-58d0-aa5d-f4e99e7cd6f2', 'drill-math-advanced', 'Math: Advanced Math', 'Equivalent expressions, quadratics, exponentials', 'drill', 'math', 'advanced_math', 'mixed', 'Factoring and simplifying, quadratic and radical equations, exponent rules and exponential models.', 21) on conflict (slug) do nothing;
insert into public.test_parts (id, test_id, part_index, title, section, duration_seconds) values ('e2eb0447-7171-5139-a840-edf1ce4c1b3d', '6a599338-97a5-58d0-aa5d-f4e99e7cd6f2', 1, 'Math: Advanced Math', 'math', 800) on conflict (test_id, part_index) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('10e41b69-e610-5027-adf0-aca0fa5e7a76', 'e2eb0447-7171-5139-a840-edf1ce4c1b3d', 1, 'advanced_math', 'equivalent_expressions', 'easy', 'mc', null, 'Which expression is equivalent to (2x + 5)(x − 1)?', '[{"key":"A","text":"2x² + 3x − 5"},{"key":"B","text":"2x² + 5x − 5"},{"key":"C","text":"2x² − 3x − 5"},{"key":"D","text":"2x² + 3x + 5"}]'::jsonb, 'A', null, 'Expanding gives 2x² − 2x + 5x − 5 = 2x² + 3x − 5. Choice B forgets the −2x term produced by multiplying 2x by −1.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('8431e10c-6a1f-51fc-aaae-57f2d2e7224a', 'e2eb0447-7171-5139-a840-edf1ce4c1b3d', 2, 'advanced_math', 'nonlinear_functions', 'easy', 'spr', null, 'If g(x) = x² + 2x, what is the value of g(5)?', null, '35', '["35.0"]'::jsonb, 'Substituting gives 25 + 10 = 35. Answering 49 treats the expression as (x + 2)² by adding before squaring.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('feb39bf1-2b6a-5e98-a480-7442e92d5252', 'e2eb0447-7171-5139-a840-edf1ce4c1b3d', 3, 'advanced_math', 'nonlinear_eq_systems', 'medium', 'mc', null, 'What is the sum of the solutions to x² − 5x − 14 = 0?', '[{"key":"A","text":"−5"},{"key":"B","text":"2"},{"key":"C","text":"5"},{"key":"D","text":"14"}]'::jsonb, 'C', null, 'The expression factors as (x − 7)(x + 2), giving roots 7 and −2 whose sum is 5, which also matches the rule that the sum of roots equals −b/a. Choice A takes b directly without changing its sign.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('c0f6749d-2b68-5d45-a6b0-4af68cf52363', 'e2eb0447-7171-5139-a840-edf1ce4c1b3d', 4, 'advanced_math', 'nonlinear_functions', 'medium', 'mc', null, 'The parabola y = −(x + 2)² + 9 has its vertex at which point?', '[{"key":"A","text":"(2, 9)"},{"key":"B","text":"(−2, 9)"},{"key":"C","text":"(−2, −9)"},{"key":"D","text":"(9, −2)"}]'::jsonb, 'B', null, 'In vertex form y = a(x − h)² + k the vertex is (h, k), and x + 2 means h = −2, so the vertex is (−2, 9). Choice A drops the sign flip that the plus inside the bracket requires.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('da688ca9-987c-5f58-a7de-f691babd7b2b', 'e2eb0447-7171-5139-a840-edf1ce4c1b3d', 5, 'advanced_math', 'equivalent_expressions', 'medium', 'spr', null, 'If 3^(2x) = 81, what is the value of x?', null, '2', '["2.0"]'::jsonb, 'Since 81 = 3⁴, the exponents match: 2x = 4, so x = 2. Answering 4 solves for the exponent rather than for x.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('984a592c-67f7-5922-ac56-e8ce8e239305', 'e2eb0447-7171-5139-a840-edf1ce4c1b3d', 6, 'advanced_math', 'nonlinear_functions', 'hard', 'mc', null, 'A quantity decays so that it halves every 4 years. If it starts at 240 units, what is the amount after 12 years?', '[{"key":"A","text":"15"},{"key":"B","text":"30"},{"key":"C","text":"60"},{"key":"D","text":"80"}]'::jsonb, 'B', null, 'Twelve years is three halvings, so the amount is 240 ÷ 2³ = 30. Choice C stops after two halvings, treating 12 years as 8.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('62b49be4-9eed-581b-a258-09e8fe549f53', 'e2eb0447-7171-5139-a840-edf1ce4c1b3d', 7, 'advanced_math', 'nonlinear_eq_systems', 'hard', 'mc', null, 'For what value of c does x² + 6x + c = 0 have exactly one real solution?', '[{"key":"A","text":"3"},{"key":"B","text":"6"},{"key":"C","text":"9"},{"key":"D","text":"36"}]'::jsonb, 'C', null, 'One real solution requires the discriminant 36 − 4c to be zero, so c = 9 and the equation becomes (x + 3)². Choice A halves the 6 without squaring it.') on conflict (id) do nothing;
insert into public.questions (id, part_id, order_index, domain_id, skill_id, difficulty, question_type, passage, prompt, choices, correct_answer, accepted_answers, explanation) values ('0bca69e1-bd85-5065-a09f-a370566c3dad', 'e2eb0447-7171-5139-a840-edf1ce4c1b3d', 8, 'advanced_math', 'equivalent_expressions', 'hard', 'mc', null, 'Which expression is equivalent to (x⁵y²)³ / (x²y)²?', '[{"key":"A","text":"x¹¹y⁴"},{"key":"B","text":"x¹³y⁴"},{"key":"C","text":"x¹¹y⁵"},{"key":"D","text":"x⁷y⁴"}]'::jsonb, 'A', null, 'The numerator becomes x¹⁵y⁶ and the denominator x⁴y², so subtracting exponents gives x¹¹y⁴. Choice B subtracts only 2 from the x exponent, forgetting that the denominator is also squared.') on conflict (id) do nothing;
